  check::close(n2.coef.p_value[1], 6.6878388602383461e-07, 1e-4, "summary(n2)$coef[2, 4]");  // summary(n2)$coef[2, 4]
  check::close(n2.sigma, 7.9134632674327907, 1e-5, "summary(n2)$sigma");  // summary(n2)$sigma
  check::close(n2.rss, 626.22900885008062, 1e-6, "deviance(n2)");  // deviance(n2)
    check::ok(n2.df_residual == 10, "summary(n2)$df[2]");
  check::close(n2.cov_unscaled(0, 0), 0.38694650663822944, 1e-5, "summary(n2)$cov.unscaled[1, 1]");  // summary(n2)$cov.unscaled[1, 1]
